import React, { useState } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Navbar from './Components/Navbar/Navbar';
import Hero from './Components/Hero/Hero'; 
import Footer from './Components/Footer/Footer';
import Home from './Pages/Home';
import LoginSignup from './Pages/LoginSignup';
import Products from './Pages/Products';
import About from './Pages/About';
import Contact from './Pages/Contact';
import Cart from './Pages/Cart';
import AdminDashboard from './Pages/AdminDashboard';
import ProtectedRoute from './Components/ProtectedRoute';
import SellerDashboard from './Pages/SellerDashboard';
import AddProductPage from './Pages/AddProductPage';
import Orders from './Pages/Orders';
import Wishlist from './Pages/Wishlist';

function StoreLayout() {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const handleSelectProduct = (product) => {
    setSelectedProduct(product);
  };

  const handleCloseModal = () => {
    setSelectedProduct(null);
  };

  // Ultra-robust feature parser supporting arrays, JSON strings, and all naming variations
  const renderFeatures = (product) => {
    if (!product) return null;

    const raw = product.keyFeatures || 
                product.features || 
                product.highlights || 
                product.key_features || 
                product.keyFeature || 
                product.bulletPoints;

    if (!raw) return null;

    let parsedList = raw;

    if (typeof raw === 'string') {
      try {
        const jsonParsed = JSON.parse(raw);
        if (Array.isArray(jsonParsed)) {
          parsedList = jsonParsed;
        }
      } catch (e) {
        // Not JSON, keep as string
      }
    }

    if (Array.isArray(parsedList)) {
      return (
        <ul style={{ margin: 0, paddingLeft: '18px', fontSize: '13px', color: '#64748b', lineHeight: '1.5' }}>
          {parsedList.map((feat, idx) => (
            <li key={idx} style={{ marginBottom: '4px' }}>{feat}</li>
          ))}
        </ul>
      );
    }

    return (
      <p style={{ margin: 0, fontSize: '13px', color: '#64748b', whiteSpace: 'pre-line', lineHeight: '1.5' }}>
        {String(parsedList)}
      </p>
    );
  };

  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', margin: 0, padding: 0, backgroundColor: '#f8f9fc', position: 'relative' }}>
      <style>{`
        body, html {
          margin: 0 !important;
          padding: 0 !important;
          overflow-x: hidden !important;
        }
      `}</style>

      {/* Sidebar Navigation */}
      <div style={{ 
        width: '250px', 
        minWidth: '250px', 
        height: '100vh', 
        position: 'sticky', 
        top: '0', 
        left: '0',
        display: isSidebarOpen ? 'block' : 'none',
        zIndex: 1000,
        backgroundColor: '#0f172a',
        flexShrink: 0
      }}>
        <Navbar />
      </div>

      {/* Main Content Area */}
      <div style={{ 
        display: 'flex', 
        flexDirection: 'column', 
        flex: 1, 
        minHeight: '100vh', 
        width: '100%',
        overflowX: 'hidden'
      }}>

        <Hero onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} />

        <main style={{ 
          flex: 1, 
          padding: '0px', 
          boxSizing: 'border-box', 
          width: '100%', 
          display: 'flex', 
          flexDirection: 'column', 
          alignItems:'stretch'
        }}>

          <div style={{ width: '100%', maxWidth: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <Routes>
              <Route path='/' element={<Home onSelectProduct={handleSelectProduct} />} />
              <Route path='/products' element={<Products onSelectProduct={handleSelectProduct} />} />
              <Route path='/about' element={<About />} />
              <Route path='/contact' element={<Contact />} />
              <Route path='/login' element={<LoginSignup />} />
              <Route path='/cart' element={<Cart />} />
              <Route path='/orders' element={<Orders />} />
              <Route path='/Wishlist' element={<Wishlist onSelectProduct={handleSelectProduct} />} />
            </Routes>
          </div>
        </main>

        <Footer />
      </div>

      {/* Product Detail Modal Popup */}
      {selectedProduct && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          backgroundColor: 'rgba(0, 0, 0, 0.6)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 9999,
          padding: '20px'
        }}>
          <div style={{
            backgroundColor: '#fff',
            borderRadius: '12px',
            maxWidth: '850px',
            width: '100%',
            maxHeight: '90vh',
            overflowY: 'auto',
            padding: '30px',
            position: 'relative',
            boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.3)'
          }}>
            <button 
              onClick={handleCloseModal}
              style={{
                position: 'absolute',
                top: '15px',
                right: '15px',
                background: 'none',
                border: 'none',
                fontSize: '22px',
                cursor: 'pointer',
                color: '#64748b',
                zIndex: 10
              }}
            >
              &times;
            </button>

            <div style={{ display: 'flex', gap: '30px', flexWrap: 'wrap', alignItems: 'flex-start' }}>
              {/* Left Column: Image */}
              <div style={{ flex: '1 1 320px', display: 'flex', justifyContent: 'center', alignItems: 'center', position: 'sticky', top: 0 }}>
                <img 
                  src={selectedProduct.image || selectedProduct.images?.[0]} 
                  alt={selectedProduct.title || selectedProduct.name} 
                  style={{ maxWidth: '100%', maxHeight: '380px', objectFit: 'contain', borderRadius: '8px' }} 
                />
              </div>

              {/* Right Column: Details */}
              <div style={{ flex: '1 1 400px', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                <h2 style={{ margin: 0, fontSize: '22px', color: '#0f172a', lineHeight: '1.3' }}>
                  {selectedProduct.title || selectedProduct.name}
                </h2>

                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                  <span style={{ fontSize: '24px', fontWeight: 'bold', color: '#6366f1' }}>{selectedProduct.price}</span>
                  {selectedProduct.originalPrice && (
                    <span style={{ fontSize: '16px', color: '#94a3b8', textDecoration: 'line-through' }}>{selectedProduct.originalPrice}</span>
                  )}
                </div>

                {/* Add to Cart Button positioned right under the price */}
                <button 
                  onClick={() => {
                    const cartItems = JSON.parse(localStorage.getItem('cartItems')) || [];
                    const idx = cartItems.findIndex(i => (i._id || i.id) === (selectedProduct._id || selectedProduct.id));
                    if (idx > -1) {
                      cartItems[idx].quantity = (cartItems[idx].quantity || 1) + 1;
                    } else {
                      cartItems.push({ ...selectedProduct, quantity: 1 });
                    }
                    localStorage.setItem('cartItems', JSON.stringify(cartItems));
                    alert('Item added to cart successfully!');
                    handleCloseModal();
                  }}
                  style={{
                    backgroundColor: '#130352',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '6px',
                    padding: '12px',
                    fontWeight: 'bold',
                    cursor: 'pointer',
                    fontSize: '15px',
                    width: '100%',
                    textAlign: 'center'
                  }}
                >
                  Add to Cart
                </button>

                <hr style={{ border: 'none', borderTop: '1px solid #e2e8f0', margin: '5px 0' }} />

                <div>
                  <h4 style={{ margin: '0 0 5px 0', fontSize: '14px', color: '#334155' }}>Product Description</h4>
                  <p style={{ margin: 0, fontSize: '14px', color: '#64748b', lineHeight: '1.5' }}>
                    {selectedProduct.description || 'Explore high quality features and seamless compatibility with this reliable item.'}
                  </p>
                </div>

                {/* Key Features Section */}
                <div>
                  <h4 style={{ margin: '0 0 5px 0', fontSize: '14px', color: '#334155' }}>Key Features</h4>
                  {renderFeatures(selectedProduct) || (
                    <p style={{ margin: 0, fontSize: '13px', color: '#94a3b8', fontStyle: 'italic' }}>No key features specified.</p>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/seller/*" element={<SellerDashboard />} />
        <Route path="/seller" element={<SellerDashboard />} />
        <Route path="/seller/add-product" element={<AddProductPage />} />
        <Route 
          path="/admin" 
          element={
            <ProtectedRoute adminOnly={true}>
              <AdminDashboard />
            </ProtectedRoute>
          } 
        />
        <Route path="/*" element={<StoreLayout />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
